import{c as t,Q as n,j as r,m as o}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Connecting meshO Prime and radios","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/connecting-prime-and-radios.md","filePath":"user/running-the-event/connecting-prime-and-radios.md"}'),a={name:"user/running-the-event/connecting-prime-and-radios.md"};function s(i,e,h,d,c,l){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="connecting-mesho-prime-and-radios" tabindex="-1">Connecting meshO Prime and radios <a class="header-anchor" href="#connecting-mesho-prime-and-radios" aria-label="Permalink to &quot;Connecting meshO Prime and radios&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators setting up the radio network before and during the event.</p><p><strong>meshO Prime</strong> is the hub of meshO&#39;s own radio system. You plug it into the Manager computer over USB, and it collects <strong>radio punches</strong> from <strong>meshO Control</strong> units out at the controls, plus location and status from any <strong>meshO Athlete</strong> units competitors are carrying. Those punches drive the live picture — Leaderboard, Commentary, Tracking and Live View — long before a single card is downloaded at the finish, and also helps you keep track of who is still On Course.</p><p>Radios are optional. Without Prime, Manager still runs the whole event from card downloads at the finish; you just don&#39;t get the live radio picture. See <a href="./../what-is-mesho-manager/">How meshO Manager works</a>.</p><h2 id="connecting-prime" tabindex="-1">Connecting Prime <a class="header-anchor" href="#connecting-prime" aria-label="Permalink to &quot;Connecting Prime&quot;">​</a></h2><p>Plug meshO Prime into the Manager computer with a USB cable. <strong>Manager finds it automatically — there&#39;s no COM port to choose.</strong> Open the <strong>Devices</strong> page (the device icon on the events list, before an event is live): it shows <em>Searching for meshO Prime</em> until the unit is detected, then <strong>Connected</strong>.</p><p>The Devices page is where you prepare the radio hardware ahead of the event. It has two modes:</p><ul><li><strong>Manage</strong> — see the Prime and every Control and Athlete unit it can reach, set <strong>TX power</strong>, calibrate the battery reading, power a unit off, and other functions.</li><li><strong>Firmware</strong> — view the current firmware version installed, and upgrade the devices firmware if a new version is available.</li></ul><h2 id="turning-radio-punches-on-for-an-event" tabindex="-1">Turning radio punches on for an event <a class="header-anchor" href="#turning-radio-punches-on-for-an-event" aria-label="Permalink to &quot;Turning radio punches on for an event&quot;">​</a></h2><p>Radio punches are enabled <strong>per event</strong>. Open <strong>Edit event details</strong> (the cog on the dashboard&#39;s event card) and go to the <strong>Radio Controls</strong> tab:</p><ul><li><strong>meshO Prime</strong> — switch this on to collect radio punches from Prime. The live radio views (<strong>Radios</strong>, <strong>Tracking</strong>, <strong>Live View</strong>) only appear once it&#39;s on.</li><li><strong>Forward Radio Punches</strong> — send punches on to another system (see <a href="./radio-punches#forwarding-and-receiving-punches">Radio punches</a>).</li><li><strong>Accept SIRAP Punches</strong> — receive punches from an upstream system instead of, or as well as, Prime.</li></ul><p>This tab is also where you set the <strong>Start / Finish / Check unit codes</strong> so Manager classifies those punches correctly — see <a href="./../event-setup/controls-and-radio-controls#start-finish-and-check-codes">Controls and radio controls</a>.</p><h2 id="watching-the-radio-network-during-the-event" tabindex="-1">Watching the radio network during the event <a class="header-anchor" href="#watching-the-radio-network-during-the-event" aria-label="Permalink to &quot;Watching the radio network during the event&quot;">​</a></h2><p>Once the event is live, open the <strong>Radios</strong> page (under the live section of the event navigation). It shows the health of the whole radio network:</p><ul><li><strong>Prime unit status</strong> — serial number, firmware, last-seen time, uptime, the number of controls registered, and a punch tally (<strong>Received / Stored / Unsent</strong>).</li><li><strong>meshO Control</strong> units — one row each, with the <strong>control number</strong> the unit is assigned to, <strong>battery</strong>, <strong>location</strong> and <strong>last seen</strong>. While the event is running you also see whether each is <strong>Listening</strong> (<em>Active</em> / <em>Paused</em>), its <strong>TX power</strong>, and <strong>Auto-standby</strong>.</li><li><strong>meshO Athlete</strong> units — battery, location, last-seen and firmware for each tracker.</li></ul><p>Each control&#39;s row has an actions menu — <strong>Identify</strong> (blink its LED to find it), <strong>Listen for radio punches</strong> / <strong>Pause listening</strong>, <strong>TX power</strong>, auto-standby, <strong>Power off</strong> and <strong>Delete</strong>.</p><p>For an at-a-glance version, the <strong>Field Units Status</strong> card on the <a href="./dashboard">dashboard</a> shows a punch-activity sparkline and a coloured health dot per control (green = reporting, orange = quiet for a few minutes, red = silent, grey = never heard from), and flags low batteries and other alerts. Click the card to jump to the Radios page, or <strong>Diagnostics</strong> if Prime is not being detected.</p><blockquote><p><strong>Recommended hardware:</strong> use SRR units (e.g. BSF8-SRR / BSF9-SRR) for the start, finish and check so both manual (contact) and contactless (SIAC &quot;air&quot;) punches are captured and broadcast live. Require a punch at the start (not a Beacon Start); a Beacon Finish is fine. See <a href="./safety-check#recommended-start-finish-hardware">Safety check</a>.</p></blockquote><h2 id="when-prime-drops-out" tabindex="-1">When Prime drops out <a class="header-anchor" href="#when-prime-drops-out" aria-label="Permalink to &quot;When Prime drops out&quot;">​</a></h2><p>If the USB cable is pulled or the connection resets, the Devices page and the Field Units card go back to <em>Searching</em>. Reconnect the cable and Manager picks Prime up again automatically. See <a href="./radio-punches#recovering-missed-punches">Radio punches</a>.</p><p>For practice and testing without a real event, Manager can <strong>replay</strong> a captured data file through the same path — see <a href="./dashboard">The event dashboard</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./radio-punches">Radio punches</a> — the live feed of punches and how to act on it</li><li><a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a> — naming radio controls and the Start/Finish/Check codes</li><li><a href="./dashboard">The event dashboard</a> — the Field Units Status card and the live counts</li><li><a href="./safety-check">Safety check: accounting for everyone</a> — why start/finish radio coverage matters</li><li><a href="./../reference/troubleshooting">Troubleshooting</a> — when something isn&#39;t reporting</li></ul>',23)])])}const p=t(a,[["render",s]]);export{u as __pageData,p as default};
